<script setup lang="ts">
import { computed } from 'vue'; import { useRoute } from 'vue-router'; import AppStatusChip from '@/Components/AppStatusChip.vue'; import PageHeader from '@/Components/layout/PageHeader.vue'; import QrCodeCard from '@/Components/sites/QrCodeCard.vue'; import { useAdministratorStore } from '@/stores/administrator.store'
const route = useRoute(); const store = useAdministratorStore(); const site = computed(() => store.getSiteById(route.params.siteId as string)); const manager = computed(() => site.value ? store.getUserById(site.value.managerId) : undefined)
</script>
<template><div class="mx-auto w-full max-w-[1100px]"><PageHeader><template #title>{{ site?.name ?? 'Site introuvable' }}</template><template #description>Configuration géographique, responsable et QR code.</template><template #actions><v-btn variant="outlined" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-sites' }">Retour</v-btn><v-btn v-if="site" color="primary" prepend-icon="mdi-pencil-outline" :to="{ name: 'admin-site-edit', params: { siteId: site.id } }">Modifier</v-btn></template></PageHeader><v-alert v-if="!site" type="error" variant="tonal" title="Site introuvable" /><div v-else class="grid gap-6 lg:grid-cols-[1fr_360px]"><v-card><v-card-title class="flex items-center justify-between px-6 py-5"><span>Informations du site</span><AppStatusChip :status="site.status" /></v-card-title><v-divider /><v-card-text class="grid gap-5 px-6 py-6 sm:grid-cols-2"><div><p class="text-xs text-[#848484]">Adresse</p><p class="mt-1 font-medium">{{ site.address }}, {{ site.city }}</p></div><div><p class="text-xs text-[#848484]">Responsable</p><p class="mt-1 font-medium">{{ manager ? `${manager.firstName} ${manager.lastName}` : 'Non affecté' }}</p></div><div><p class="text-xs text-[#848484]">Coordonnées</p><p class="mt-1 font-medium">{{ site.latitude }}, {{ site.longitude }}</p></div><div><p class="text-xs text-[#848484]">Rayon de présence</p><p class="mt-1 font-medium">{{ site.radiusM }} mètres</p></div></v-card-text><v-divider /><v-card-actions class="px-6 py-4"><v-btn variant="tonal" :color="site.status === 'active' ? 'error' : 'success'" @click="store.toggleSiteStatus(site.id)">{{ site.status === 'active' ? 'Désactiver le site' : 'Activer le site' }}</v-btn></v-card-actions></v-card><QrCodeCard :site="site" @details="() => {}" @regenerate="store.regenerateQrCode($event.id)" /></div></div></template>
